[CmdletBinding()]param([string]$Root='../..',[Parameter(Mandatory)][string]$AppId,[ValidateSet('major','minor','patch')][string]$Bump='minor',[string]$InitialVersion='0.1.0',[string]$LegacyId)
Import-Module (Join-Path $PSScriptRoot 'Discovery.Release.psm1') -Force
if(-not $env:GITHUB_OUTPUT){throw 'GITHUB_OUTPUT is required'};if([string]::IsNullOrWhiteSpace($InitialVersion)){$InitialVersion='0.1.0'};$ids=@($AppId);if($LegacyId){$ids+=$LegacyId};$tags=@($ids|ForEach-Object{Get-ApplicationTags $Root $_}|Select-Object -Unique);$next=Get-NextRcVersion $AppId $tags $Bump $InitialVersion $(if($LegacyId){@($LegacyId)}else{@()});Add-Content -LiteralPath $env:GITHUB_OUTPUT -Value "version=$($next.version)`ntag=$($next.tag)`ntarget=$($next.target.major).$($next.target.minor).$($next.target.patch)`nrc=$($next.rc)" -Encoding utf8
